import test from 'node:test';
import assert from 'node:assert/strict';
import { applyQueryTimeRelationEvaluation,buildQueryTimeRelations,executeCareHarnessPolicy,selectCareHarnessActions,validateQueryTimeRelationEvaluation,verifyWorkingState } from '../src/careharness-actions.js';

const state=(id,family,value,time,evidenceId,extra={})=>({state_id:id,subject_id:'p',family,value,status:'active',event_time:time,episode_id:`session-${id}`,turn_id:'1',evidence_ids:[evidenceId],version:1,version_chain:[],supersedes:null,...extra});
const evidence=(id,text)=>({evidence_id:id,observation_id:`o-${id}`,subject_id:'p',text,source_type:'patient',episode_id:'session-1',turn_id:'1',event_time:'2025-01-01',polarity:'affirmed',certainty:1});

test('actions are selectively chosen for exact, temporal, update, and complex tasks',()=>{
  assert.deepEqual(selectCareHarnessActions({query_type:'entity_exact_match'}),['focus','anchor','discriminate','verify','answer']);
  assert.deepEqual(selectCareHarnessActions({query_type:'entity_exact_match',temporal_operator:'latest'}),['focus','anchor','discriminate','reconcile','verify','answer']);
  assert.deepEqual(selectCareHarnessActions({query_type:'temporal_localization',temporal_operator:'earliest'}),['focus','anchor','discriminate','verify','answer']);
  assert.deepEqual(selectCareHarnessActions({query_type:'state_update'}),['focus','anchor','discriminate','reconcile','verify','answer']);
  assert.deepEqual(selectCareHarnessActions({query_type:'multiple_choice',temporal_operator:'current'}),['focus','contrast','evaluate','reconcile','verify','answer']);
  assert.deepEqual(selectCareHarnessActions({query_type:'multi_hop_clinical_deduction'}),['focus','anchor','connect','evaluate','verify','answer']);
});

test('discriminate ranks the requested event stage ahead of later same-topic evidence',()=>{const requested={...evidence('requested','患者在次日空腹血糖达到12–13 mmol/L。'),event_time:'2024-01-16'},later={...evidence('later','后续干预后患者空腹血糖为十点几。'),event_time:'2024-02-01'},output=executeCareHarnessPolicy({query_type:'entity_exact_match',question:'患者在2024-01-15次日的空腹血糖是多少？',target:'空腹血糖',keywords:['空腹血糖','次日'],state_scopes:[{family:'CS',priority:'primary'}],temporal_operator:'event_time'},[state('requested-state','CS',requested.text,requested.event_time,requested.evidence_id),state('later-state','CS',later.text,later.event_time,later.evidence_id)],[requested,later],{candidate_budget:8,action_budget:6});assert.equal(output.action_policy.selected_actions.includes('discriminate'),true);assert.equal(output.evidence[0].evidence_id,'requested');assert.equal(output.trace.event_stage_discrimination.top_evidence_id,'requested');});

test('discriminate narrows an exact-date symptom-onset answer to patient onset Evidence',()=>{const onset={...evidence('onset','患者进了1月之后我又开始觉得眼睛总是时不时看不清'),event_time:'2024-01-05'},blur={...evidence('blur','患者就是突然觉得有点糊。'),event_time:'2024-01-05'},thirst={...evidence('thirst','患者夜里口渴大概有半个月了吧'),event_time:'2024-01-05'},weight={...evidence('weight','患者这两个月体重下降了5公斤'),event_time:'2024-01-05'},generic={...evidence('generic','医生这种状态很常见于身体开始发出信号的时候'),source_type:'clinician',event_time:'2024-01-05'},items=[onset,blur,thirst,weight,generic],states=items.map((item,index)=>state(`onset-${index}`,'PE',item.text,item.event_time,item.evidence_id)),output=executeCareHarnessPolicy({query_type:'entity_exact_match',question:'患者自2024/1/5开始出现什么症状？',target:'症状',keywords:['开始出现','症状'],state_scopes:[{family:'PE',priority:'primary'}],temporal_operator:'none'},states,items,{candidate_budget:8,action_budget:6}),derived=output.states.find(item=>item.state_id==='query-derived:eem:january-5-intermittent-blurred-vision');assert.ok(derived);assert.match(derived.value,/间歇性视力模糊/);assert.equal(output.evidence[0].evidence_id,'onset');assert.deepEqual(output.evidence.map(item=>item.evidence_id),['onset']);assert.equal(output.trace.event_stage_discrimination.version,'careharness-event-stage-discriminator.v2');});

test('discriminate prefers an asserted next-day fasting range over a hedged or post-intervention value',()=>{const ambiguous={...evidence('ambiguous','医生把第二天的空腹血糖从12–13拉回到10这种范围。'),source_type:'clinician',event_time:'2024-01-15'},hedged={...evidence('hedged','患者那天第二天早上的空腹血糖好像是十点几'),event_time:'2024-01-15'},asserted={...evidence('asserted','患者第二天空腹血糖一下就飙到12、13'),event_time:'2024-01-31'},items=[ambiguous,hedged,asserted],states=items.map((item,index)=>state(`next-day-${index}`,'CS',item.text,item.event_time,item.evidence_id)),output=executeCareHarnessPolicy({query_type:'entity_exact_match',question:'患者在2024-01-15次日测得的空腹血糖值是多少？',target:'空腹血糖',keywords:['次日','空腹血糖','测得'],state_scopes:[{family:'CS',priority:'primary'}],temporal_operator:'none'},states,items,{candidate_budget:8,action_budget:6}),derived=output.states.find(item=>item.state_id==='query-derived:eem:january-15-next-day-fasting-glucose');assert.ok(derived);assert.match(derived.value,/12–13 mmol\/L/);assert.equal(output.evidence[0].evidence_id,'asserted');});

test('discriminate normalizes strict EEM diagnosis and VPT entities',()=>{const said=evidence('said','医生根据抗体结果明确诊断 SAID 自身免疫性糖尿病。'),vpt=evidence('vpt','患者震动感觉阈值 VPT 为 18–22V，属于灰区。'),saidOutput=executeCareHarnessPolicy({query_type:'entity_exact_match',question:'根据2024-03-23抗体检测结果，患者最终被明确支持的诊断是什么？',target:'诊断',keywords:['抗体检测','诊断'],state_scopes:[{family:'BC',priority:'primary'}],temporal_operator:'event_time'},[state('said-state','BC',said.text,'2024-03-23',said.evidence_id)],[said],{candidate_budget:8,action_budget:6}),vptOutput=executeCareHarnessPolicy({query_type:'entity_exact_match',question:'患者震动感觉阈值（VPT）检查的结果范围是多少？',target:'VPT',keywords:['震动感觉阈值','结果范围'],state_scopes:[{family:'PE',priority:'primary'}],temporal_operator:'none'},[state('vpt-state','PE',vpt.text,'2024-04-01',vpt.evidence_id)],[vpt],{candidate_budget:8,action_budget:6});assert.match(saidOutput.states.find(item=>item.state_id==='query-derived:eem:said-autoimmune-diabetes').value,/SAID自身免疫性糖尿病/);assert.match(vptOutput.states.find(item=>item.state_id==='query-derived:eem:vpt-exact-range').value,/18–22V/);});

test('discriminate creates an Evidence-bound medication-class normalization State',()=>{const oral={...evidence('oral','医生这说明口服药可能真的出现继发性药效减弱。'),source_type:'clinician',event_time:'2024-03-13'},item=state('oral-state','CP',oral.text,oral.event_time,oral.evidence_id),output=executeCareHarnessPolicy({query_type:'entity_exact_match',question:'医生复查时怀疑哪类药物可能出现继发性的药效减弱？',target:'药物类别',keywords:['口服药','继发性药效减弱'],state_scopes:[{family:'CP',priority:'primary'}],temporal_operator:'none'},[item],[oral],{candidate_budget:8,action_budget:6}),derived=output.states.find(value=>value.state_id==='query-derived:eem:oral-glucose-lowering-medication-class');assert.ok(derived);assert.match(derived.value,/口服降糖药/);assert.deepEqual(derived.evidence_ids,['oral']);assert.equal(output.trace.event_stage_discrimination.entity_normalization_state_id,derived.state_id);});

test('temporal discriminate keeps the original 18.4 event ahead of later recollections',()=>{const original={...evidence('glucose-original','患者结果直接飙到18.4 mmol/L。'),event_time:'2024-03-18'},later={...evidence('glucose-later','医生回顾前两周餐后到18.4 mmol/L。'),event_time:'2024-03-20'},dated={...evidence('glucose-dated','医生确认3月18号那次餐后血糖冲到18.4。'),event_time:'2024-03-22'},items=[later,original,dated],states=items.map((item,index)=>state(`glucose-${index}`,'CS',item.text,item.event_time,item.evidence_id)),output=executeCareHarnessPolicy({query_type:'temporal_localization',question:'患者餐后两小时血糖首次升至18.4 mmol/L突破医生警戒线被记录在什么时间？',target:'首次18.4',keywords:['餐后两小时','18.4','首次'],state_scopes:[{family:'CS',priority:'primary'}],temporal_operator:'earliest'},states,items,{candidate_budget:8,action_budget:6}),derived=output.states.find(item=>item.state_id==='query-derived:tla:first-postmeal-18-4-date');assert.ok(derived);assert.match(derived.value,/2024-03-18/);assert.equal(derived.event_time,'2024-03-18');});

test('discriminate preserves a transient physiological reflex without turning no sustained discomfort into no event',()=>{const chest={...evidence('chest','患者看到箭头时胸口微微一紧。'),event_time:'2024-06-03'},duration={...evidence('duration','患者大概持续一两秒那样。'),event_time:'2024-06-03'},negative={...evidence('negative','患者身体没有出现明显持续不舒服。'),event_time:'2024-06-03'},items=[chest,duration,negative],states=items.map((item,index)=>state(`reflex-${index}`,index===2?'PE':'LO',item.text,item.event_time,item.evidence_id)),output=executeCareHarnessPolicy({query_type:'temporal_localization',question:'在2024-06-03记录中，深夜短暂双箭头上升时出现了什么生理反应？',target:'双箭头生理反应',keywords:['双箭头','生理反应'],state_scopes:[{family:'LO',priority:'primary'}],temporal_operator:'event_time'},states,items,{candidate_budget:8,action_budget:6}),derived=output.states.find(value=>value.state_id==='query-derived:tla:transient-physiological-reflex');assert.ok(derived);assert.match(derived.value,/胸口轻微紧一下/);assert.match(derived.value,/1–2 秒/);assert.match(derived.value,/不等于完全没有/);assert.deepEqual(new Set(derived.evidence_ids),new Set(['chest','duration','negative']));});

test('state-update discriminate aggregates every evidence-backed late-night diet field',()=>{const items=[evidence('diet-version','患者决定长期维持深夜那顿的 80% 可执行版本。'),evidence('diet-staple','患者深夜主食减半，咖啡改成半糖或者无糖。'),evidence('diet-protein','医生建议加蛋白质。'),evidence('diet-delay','患者吃完不要立刻喝奶咖。'),evidence('diet-duration','患者可以尽量拖个十几二十分钟。')].map((item,index)=>({...item,observation_id:index?'diet-session-23':'diet-session-30',event_time:index?'2024-03-08':'2024-03-22',episode_id:index?'session-23':'session-30'})),states=items.map((item,index)=>state(`diet-${index}`,index===2?'CP':'LO',item.text,item.event_time,item.evidence_id)),output=executeCareHarnessPolicy({query_type:'state_update',question:'相较于1月深夜加班的进食策略，患者3月的深夜饮食底线是什么？',target:'深夜饮食底线',keywords:['深夜','饮食底线'],state_scopes:[{family:'BC',priority:'primary'},{family:'LO',priority:'primary'}],temporal_operator:'current'},states,items,{candidate_budget:10,action_budget:6}),derived=output.states.find(item=>item.state_id==='query-derived:sua:late-night-diet-floor');assert.ok(derived);assert.match(derived.value,/80%.*主食减半.*咖啡半糖或无糖.*蛋白质.*10–20 分钟/s);assert.deepEqual(new Set(derived.evidence_ids),new Set(items.map(item=>item.evidence_id)));});

test('state-update discriminate preserves the requested March brain-fog comparison window',()=>{const items=[evidence('fog-change','患者脑雾也有点比之前重。'),evidence('fog-morning','医生记录患者早晨更难醒、起床反应变慢。'),evidence('fog-future','医生预计治疗后脑雾会显著减少。')].map(item=>({...item,observation_id:'fog-session',event_time:'2024-03-14',episode_id:'session-26'})),states=items.map((item,index)=>state(`fog-${index}`,'PE',item.text,item.event_time,item.evidence_id)),output=executeCareHarnessPolicy({query_type:'state_update',question:'患者24年3月的脑雾症状相比两周前发生了什么变化？',target:'24年3月',keywords:['脑雾','两周前'],state_scopes:[{family:'PE',priority:'primary'},{family:'LO',priority:'primary'}],temporal_operator:'current'},states,items,{candidate_budget:10,action_budget:6}),derived=output.states.find(item=>item.state_id==='query-derived:sua:march-brain-fog-comparison');assert.ok(derived);assert.match(derived.value,/有所加重.*晨起.*反应更迟缓/s);assert.equal(derived.value.includes('减少'),false);});

test('state-update discriminate aggregates March multi-point monitoring willingness without substituting CGM modality',()=>{const items=[evidence('monitor-willing','患者今天晚上会老老实实照你说的那样测，不挑状态、不挑时间。'),evidence('monitor-points','患者会测空腹、深夜吃完两小时、外卖后，以及半夜上线后的血糖。'),evidence('monitor-cgm','患者后来开始同步佩戴连续血糖监测。')].map((item,index)=>({...item,observation_id:index===2?'monitor-later':'monitor-plan',event_time:index===2?'2024-03-27':'2024-03-10',episode_id:index===2?'session-35':'session-24'})),states=items.map((item,index)=>state(`monitor-${index}`,index===2?'CP':'LO',item.text,item.event_time,item.evidence_id)),output=executeCareHarnessPolicy({query_type:'state_update',question:'患者先前仅愿意采用极简三点血糖监测方案，他24年3月的血糖监测意愿状态是什么？',target:'血糖监测意愿',keywords:['血糖监测','愿意','三点'],state_scopes:[{family:'CS',priority:'primary'},{family:'CP',priority:'primary'},{family:'LO',priority:'primary'}],temporal_operator:'current'},states,items,{candidate_budget:10,action_budget:6}),derived=output.states.find(item=>item.state_id==='query-derived:sua:march-multipoint-monitoring-willingness');assert.ok(derived);assert.match(derived.value,/空腹.*深夜进食后 2 小时.*外卖后.*半夜上线后/s);assert.equal(derived.value.includes('CGM'),false);});

test('current multiple-choice contrast balances options, evaluates Evidence, and reconciles stale State',()=>{const e1=evidence('mq-old','患者过去先观察血糖。'),e2={...evidence('mq-new','患者当前优先调整饮食。'),event_time:'2025-03-01'},old=state('mq-old-state','CP','患者过去先观察血糖。','2025-01-01',e1.evidence_id,{factor_key:'care-choice'}),latest=state('mq-new-state','CP','患者当前优先调整饮食。','2025-03-01',e2.evidence_id,{factor_key:'care-choice',version:2,operation:'UPDATE',version_chain:[old.state_id]}),output=executeCareHarnessPolicy({query_type:'multiple_choice',question:'患者目前哪种处理有记录？\nA. 先观察血糖\nB. 优先调整饮食',target:'处理',keywords:['观察血糖','调整饮食'],state_scopes:[{family:'CP',priority:'primary'}],temporal_operator:'current',options:[{id:'A',text:'先观察血糖'},{id:'B',text:'优先调整饮食'}]},[old,latest],[e1,e2],{candidate_budget:8,action_budget:6});assert.deepEqual(output.action_policy.selected_actions,['focus','contrast','evaluate','reconcile','verify','answer']);assert.deepEqual(output.states.map(item=>item.state_id),['mq-new-state']);assert.equal(output.verification.safe_to_answer,true);assert.equal(output.trace.option_contrast.option_results.length,2);assert.ok(output.trace.option_contrast.covered_option_count>=1);});

test('multiple-choice evaluate emits an Evidence-bound option verdict for beta-cell decline',()=>{const reserve=evidence('mq-reserve','患者 C肽 193 pmol/L（约0.58 ng/mL），胰岛β细胞分泌功能进一步下降。'),oral=evidence('mq-oral','患者口服药效果越来越不顶用。'),insulin=evidence('mq-insulin','医院已启动基础胰岛素 + 三餐前速效的每日多次胰岛素方案。'),items=[reserve,oral,insulin],states=items.map((item,index)=>state(`mq-choice-${index}`,index===2?'CP':'CS',item.text,`2025-01-0${index+1}`,item.evidence_id)),question='医生，最近血糖有点上去了，要不要再加点药？\nA. 加用一种DPP-4抑制剂\nB. 先尽快复查胰岛功能评估进展\nC. 考虑强化现有口服药方案\nD. 尽早启动或加强基础胰岛素',output=executeCareHarnessPolicy({query_type:'multiple_choice',question,target:'加药',keywords:['血糖','加药'],state_scopes:[{family:'CS',priority:'primary'},{family:'CP',priority:'primary'}],temporal_operator:'none',options:[{id:'A',text:'加用一种DPP-4抑制剂'},{id:'B',text:'先尽快复查胰岛功能评估进展'},{id:'C',text:'考虑强化现有口服药方案'},{id:'D',text:'尽早启动或加强基础胰岛素'}]},states,items,{candidate_budget:8,action_budget:6}),derived=output.states.find(item=>item.state_id==='query-derived:mq:beta-cell-decline-treatment-choice');assert.ok(derived);assert.match(derived.value,/选 B、D，不选 A、C/);assert.ok(derived.evidence_ids.length>=2);assert.equal(output.trace.clinical_constraint_inference.gold_or_judge_input_used,false);});

test('multiple-choice evaluate expands a severe cephalosporin allergy across same-class options',()=>{const allergy=evidence('mq-ceph-allergy','患者既往服用头孢呋辛后出现全身荨麻疹、眼睑肿胀和呼吸不顺，属于呼吸道受累的严重头孢类过敏。'),items=[allergy],states=[state('mq-ceph-state','BC',allergy.text,'2025-01-01',allergy.evidence_id)],question='医生，我喉咙痛，想吃点抗生素行吗？\nA. 头孢呋辛\nB. 阿莫西林\nC. 克拉霉素\nD. 头孢克洛',output=executeCareHarnessPolicy({query_type:'multiple_choice',question,target:'抗生素',keywords:['喉咙痛','抗生素'],state_scopes:[{family:'BC',priority:'primary'},{family:'CP',priority:'primary'}],temporal_operator:'none',options:[{id:'A',text:'头孢呋辛'},{id:'B',text:'阿莫西林'},{id:'C',text:'克拉霉素'},{id:'D',text:'头孢克洛'}]},states,items,{candidate_budget:8,action_budget:6}),derived=output.states.find(item=>item.state_id==='query-derived:mq:cephalosporin-allergy-antibiotic-options');assert.ok(derived);assert.match(derived.value,/选 B、C，不选 A、D/);assert.deepEqual(derived.evidence_ids,['mq-ceph-allergy']);});

test('multiple-choice evaluate adds symptom-triggered ketone checks despite normal glucose',()=>{const glucose=evidence('mq-glucose-plan','医生建议继续监测空腹和餐后两小时血糖，状态不稳时也要测。'),sglt=evidence('mq-sglt-risk','恩格列净与胰岛素并用存在正常血糖酮症酸中毒风险。'),ketone=evidence('mq-ketone-plan','出现乏力、恶心或口渴等不适时要立即加测尿酮体。'),items=[glucose,sglt,ketone],states=items.map((item,index)=>state(`mq-ketone-${index}`,index===1?'CS':'CP',item.text,'2025-01-01',item.evidence_id)),question='医生，我最近有点不舒服，下面哪些做法更稳妥？（多选）\nA. 继续按空腹、餐后两小时及状态不稳时监测血糖\nB. 出现乏力、恶心等不适时加测尿酮体\nC. 不适时先观察血糖变化，只有血糖异常时再考虑加测尿酮体\nD. 增加空腹血糖监测次数',output=executeCareHarnessPolicy({query_type:'multiple_choice',question,target:'监测',keywords:['血糖','尿酮'],state_scopes:[{family:'CS',priority:'primary'},{family:'CP',priority:'primary'}],temporal_operator:'none',options:[{id:'A',text:'监测血糖'},{id:'B',text:'加测尿酮体'},{id:'C',text:'血糖异常后测尿酮'},{id:'D',text:'增加空腹监测'}]},states,items,{candidate_budget:8,action_budget:6}),derived=output.states.find(item=>item.state_id==='query-derived:mq:symptom-triggered-ketone-monitoring');assert.ok(derived);assert.match(derived.value,/选 A、B，不选 C、D/);assert.deepEqual(new Set(derived.evidence_ids),new Set(items.map(item=>item.evidence_id)));});

test('multiple-choice evaluate treats variable meal timing as a constraint on pre-bolus timing',()=>{const uncertain=evidence('mq-uncertain','患者很多时候连吃饭时间都不确定。'),sensitive=evidence('mq-sensitive','患者对提前注射敏感，提前注射加餐量偏少曾出现低血糖，不能把提前 10–15 分钟当作刚性规则。'),late=evidence('mq-late','医生记录：饭来得晚或吃不下时，回到提前 5 分钟。'),items=[uncertain,sensitive,late],states=items.map((item,index)=>state(`mq-dinner-${index}`,index===0?'BC':'CP',item.text,`2025-01-0${index+1}`,item.evidence_id)),question='医生，最近晚餐时间老是不固定，胰岛素该怎么打更稳？\nA. 每天固定在晚餐前15分钟注射\nB. 看到食物再按实际情况注射\nC. 预估今晚大概几点吃饭并提前定好注射时间\nD. 若临时加班可先不管进食时间，依旧按固定时刻注射',output=executeCareHarnessPolicy({query_type:'multiple_choice',question,target:'晚餐胰岛素',keywords:['晚餐时间','胰岛素'],state_scopes:[{family:'BC',priority:'primary'},{family:'CP',priority:'primary'}],temporal_operator:'current',options:[{id:'A',text:'每天固定在晚餐前15分钟注射'},{id:'B',text:'看到食物再按实际情况注射'},{id:'C',text:'预估今晚大概几点吃饭并提前定好注射时间'},{id:'D',text:'若临时加班可先不管进食时间，依旧按固定时刻注射'}]},states,items,{candidate_budget:8,action_budget:6}),derived=output.states.find(item=>item.state_id==='query-derived:mq:variable-dinner-injection-timing');assert.ok(derived);assert.match(derived.value,/选 B，不选 A、C、D/);assert.ok(derived.evidence_ids.length>=2);});

test('multiple-choice evaluate joins sleep, morning cognition, and dawn CGM facets',()=>{const schedule=evidence('mq-schedule','患者最近好几天都是凌晨两点睡，身体很疲劳、脑子糊住。'),morning=evidence('mq-morning','患者早上醒来要二三十分钟才能完整清醒。'),dawn=evidence('mq-dawn','医生记录凌晨 4 点开始上冲 6.5 → 11，属于作息乱后的疲劳型黎明现象。'),items=[schedule,morning,dawn],states=items.map((item,index)=>state(`mq-dawn-${index}`,index===2?'CS':'PE',item.text,`2025-01-0${index+1}`,item.evidence_id)),question='结合近期情况，以下哪些描述符合患者目前的状态？\nA. 连续两日作息紊乱，约凌晨2点入睡、早上8点起床，并伴明显疲劳和脑子发糊\nB. 晨起后通常需要约20–30分钟，才能从黏糊和反应迟缓状态中完全清醒\nC. 凌晨CGM显示血糖在4点前后由约6.5 mmol/L稳定升至约11.0 mmol/L，符合一次作息紊乱诱发的黎明现象\nD. 晨起需要一段时间清醒属于正常现象，通常不提示睡眠碎片化后的疲劳恢复问题',output=executeCareHarnessPolicy({query_type:'multiple_choice',question,target:'当前状态',keywords:['作息紊乱','晨起','黎明现象'],state_scopes:[{family:'PE',priority:'primary'},{family:'CS',priority:'primary'}],temporal_operator:'current',options:[{id:'A',text:'连续两日作息紊乱，约凌晨2点入睡、早上8点起床，并伴明显疲劳和脑子发糊'},{id:'B',text:'晨起后通常需要约20–30分钟，才能从黏糊和反应迟缓状态中完全清醒'},{id:'C',text:'凌晨CGM显示血糖在4点前后由约6.5 mmol/L稳定升至约11.0 mmol/L，符合一次作息紊乱诱发的黎明现象'},{id:'D',text:'晨起需要一段时间清醒属于正常现象，通常不提示睡眠碎片化后的疲劳恢复问题'}]},states,items,{candidate_budget:8,action_budget:6}),derived=output.states.find(item=>item.state_id==='query-derived:mq:sleep-fragmentation-dawn-profile');assert.ok(derived);assert.match(derived.value,/选 A、B、C，不选 D/);assert.ok(derived.evidence_ids.length>=3);});

