test('query-time lineage relations require Evidence and never invent adjacency edges',()=>{
  const e1=evidence('e1','患者开始服用药物。'),e2=evidence('e2','患者血糖随后升高。'),s1=state('s1','CP','医生开始药物治疗。','2025-01-01','e1'),s2=state('s2','LO','患者血糖随后升高。','2025-02-01','e2',{supersedes:'s1',version_chain:['s1']}),relations=buildQueryTimeRelations([s1,s2],new Map([[e1.evidence_id,e1],[e2.evidence_id,e2]]));
  assert.ok(relations.some(item=>item.type==='supersedes'));
  assert.equal(relations.some(item=>item.type==='followed_by'),false);
  assert.ok(relations.every(item=>item.verified&&item.persistent===false&&item.causal_claim===false&&item.evidence_ids.length));
});

test('static CareHarness exposes persistent graph edges but does not trust source labels as semantic verification',()=>{
  const items=[state('s1','CS','患者确诊糖尿病。','2025-01-01','e1'),state('s2','CP','医生开始二甲双胍治疗。','2025-02-01','e2'),state('s3','LO','患者血糖控制持续恶化。','2025-03-01','e3')],evidenceItems=[evidence('e1','患者确诊糖尿病。'),evidence('e2','医生开始二甲双胍治疗。'),evidence('e3','患者血糖控制持续恶化。')],graphEdges=[{edge_id:'g0',subject_id:'p',from_state_id:'s1',to_state_id:'s2',edge_family:'clinical_care',relation_type:'informs',evidence_ids:['e1','e2'],confidence:.9,support_kind:'asserted',semantic_support:true,status:'verified',verified:true,persistent:true,causal_claim:false,source:'patient_graph_relation_verifier'},{edge_id:'g1',subject_id:'p',from_state_id:'s2',to_state_id:'s3',edge_family:'clinical_care',relation_type:'informs',evidence_ids:['e2','e3'],confidence:.95,support_kind:'asserted',semantic_support:true,status:'verified',verified:true,persistent:true,causal_claim:false,source:'patient_graph_relation_verifier'}],output=executeCareHarnessPolicy({query_type:'multi_hop_clinical_deduction',question:'治疗后为什么血糖仍恶化？',target:'血糖恶化',keywords:['血糖','治疗','恶化'],state_scopes:[{family:'CS',priority:'primary'},{family:'CP',priority:'primary'},{family:'LO',priority:'primary'}],temporal_operator:'history',evidence_facets:[],options:[]},items,evidenceItems,{graph_edges:graphEdges,candidate_budget:12,action_budget:6});
  assert.deepEqual(output.action_policy.selected_actions,['focus','anchor','connect','evaluate','verify','answer']);
  assert.equal(output.action_trace.at(-1).action,'answer');
  assert.equal(output.working_state.evidence.verification.gold_or_judge_input_used,false);
  assert.ok(output.trace.query_time_relations.persistent_graph_edges>0);
  assert.equal(output.working_state.control_decisions.relation.causality_asserted,false);
  assert.ok(output.relations.every(item=>item.persistent!==true||item.semantic_support===false));
  assert.equal(output.proof.verdict,'unresolved');
  assert.equal(output.action_trace.at(-1).outcome.status,'uncertain');
});

test('inference evaluate derives evidence-backed CP constraints for unsafe analgesics and failing oral therapy',()=>{
  const gi=evidence('gi','患者既往胃溃疡并出现过黑便和消化道出血。'),avoid=evidence('avoid','患者被明确要求避免 NSAIDs，布洛芬和双氯芬酸都不能碰。'),headache=executeCareHarnessPolicy({query_type:'inference_generation',question:'医生，我头胀要不要吃片止痛药？',target:'止痛药',keywords:['头胀','止痛药'],state_scopes:[{family:'BC',priority:'primary'},{family:'CP',priority:'primary'}],temporal_operator:'history'},[state('gi-state','BC',gi.text,'2025-01-01',gi.evidence_id),state('avoid-state','CP',avoid.text,'2025-01-02',avoid.evidence_id)],[gi,avoid],{candidate_budget:8,action_budget:6}),headacheState=headache.states.find(item=>item.state_id==='query-derived:ig:gi-safe-analgesia');
  assert.ok(headacheState);
  assert.match(headacheState.value,/上消化道出血.*长期避免 NSAIDs.*对乙酰氨基酚/s);
  assert.match(headacheState.value,/补水.*休息.*测血糖/s);
  assert.equal(headache.states[0].source_type,'query_time_clinical_constraint');
  assert.equal(headache.trace.clinical_constraint_inference.applied_count,1);
  assert.equal(headache.trace.clinical_constraint_inference.gold_or_judge_input_used,false);

  const failing=evidence('failing','患者规律服用口服降糖药，但感觉药效不如以前。'),flags=evidence('flags','患者近期体重下降，并有明显口渴、多饮多尿和乏力。'),workup=evidence('workup','医生建议检查糖尿病相关抗体并评估是否需要胰岛素。'),escalation=executeCareHarnessPolicy({query_type:'inference_generation',question:'医生，我要不要把降糖药加量？',target:'降糖药加量',keywords:['降糖药','加量'],state_scopes:[{family:'CS',priority:'primary'},{family:'CP',priority:'primary'}],temporal_operator:'history'},[state('failing-state','CS',failing.text,'2025-01-01',failing.evidence_id),state('flag-state','CS',flags.text,'2025-01-02',flags.evidence_id),state('workup-state','CP',workup.text,'2025-01-03',workup.evidence_id)],[failing,flags,workup],{candidate_budget:8,action_budget:6});
  assert.ok(escalation.states.some(item=>item.family==='CP'&&item.source_type==='query_time_clinical_constraint'&&item.value.includes('不应自行继续加大')));
  assert.equal(escalation.states.some(item=>item.source_type==='query_time_clinical_constraint'&&item.value.includes('已有自身免疫性糖尿病')),false);
  assert.equal(escalation.action_trace.find(item=>item.action==='evaluate').outcome.clinical_constraint_states,1);
  const escalationEvidenceIds=new Set(escalation.evidence.map(item=>item.evidence_id));
  for(const item of escalation.states)for(const evidenceId of item.evidence_ids)assert.ok(escalationEvidenceIds.has(evidenceId),`missing answer Evidence for ${item.state_id}: ${evidenceId}`);

  const stopped=evidence('stopped','患者因酮症风险已经停用恩格列净。'),diagnosis=evidence('diagnosis','GADA 强阳性，已明确确诊 SAID。'),dka=evidence('dka','患者此前出现 DKA 早期酸中毒。'),restart=executeCareHarnessPolicy({query_type:'inference_generation',question:'晨起血糖再次上升，要不要再把那个降糖药加回去？',target:'降糖药加回',keywords:['降糖药','加回'],state_scopes:[{family:'CS',priority:'primary'},{family:'CP',priority:'primary'}],temporal_operator:'history'},[state('stopped-state','CS',stopped.text,'2025-01-01',stopped.evidence_id),state('diagnosis-state','CS',diagnosis.text,'2025-01-02',diagnosis.evidence_id),state('dka-state','CS',dka.text,'2025-01-03',dka.evidence_id)],[stopped,diagnosis,dka],{candidate_budget:8,action_budget:6});
  assert.ok(restart.states.some(item=>item.source_type==='query_time_clinical_constraint'&&item.value.includes('SGLT2')&&item.value.includes('不应自行加回')));
});

test('inference evaluate blocks symptom-based monitoring withdrawal and early DKA departure',()=>{
  const retina=evidence('retina','患者在2024-06-03眼底有散在微血管瘤和少量硬性渗出，已诊断轻度 NPDR。'),said=evidence('said-risk','患者已经确诊 SAID 自身免疫性糖尿病。'),silent=executeCareHarnessPolicy({query_type:'inference_generation',question:'最近夜里血糖上冲不难受了，还要盯吗？',target:'夜间血糖',keywords:['夜里血糖','不难受','盯'],state_scopes:[{family:'CS',priority:'primary'}],temporal_operator:'history'},[state('retina-state','CS',retina.text,'2024-06-03',retina.evidence_id),state('said-state','BC',said.text,'2024-03-23',said.evidence_id)],[retina,said],{candidate_budget:8,action_budget:6}),silentState=silent.states.find(item=>item.state_id==='query-derived:ig:silent-hyperglycemia-monitoring');
  assert.ok(silentState);
  assert.match(silentState.value,/2024-06-03.*SAID.*不敏感.*不能.*神经更敏感/s);
  assert.match(silentState.value,/保持原有深夜监测节奏/);

  const improved=evidence('improved','患者站起眼前发白已从隔几天一次减少到整月2–3次。'),high=evidence('high','患者空腹血糖仍常在10–11 mmol/L，餐后曾明显飙升。'),risk=evidence('risk','患者曾有尿酮体 ++、酸中毒和短暂意识模糊。'),monitor=executeCareHarnessPolicy({query_type:'inference_generation',question:'最近站起来时眼前发白少了不少，能少测点血糖吗？',target:'减少血糖监测',keywords:['眼前发白','少测血糖'],state_scopes:[{family:'CS',priority:'primary'}],temporal_operator:'none'},[state('improved-state','LO',improved.text,'2025-01-01',improved.evidence_id),state('high-state','CS',high.text,'2025-02-01',high.evidence_id),state('risk-state','CS',risk.text,'2025-03-01',risk.evidence_id)],[improved,high,risk],{candidate_budget:8,action_budget:6});
  assert.ok(monitor.states.some(item=>item.state_id==='query-derived:ig:symptom-improvement-no-monitoring-reduction'&&item.value.includes('维持或适度增加监测')));

  const acid=evidence('acid','患者血 pH 7.28，已经处于酸中毒范围。'),ketone=evidence('ketone','患者尿酮体 ++，符合 DKA 早期。'),neuro=evidence('neuro','患者曾短暂意识模糊并呼吸偏快。'),leave=executeCareHarnessPolicy({query_type:'inference_generation',question:'补液后我能早点走吗？',target:'补液后离开',keywords:['补液','早点走'],state_scopes:[{family:'CS',priority:'primary'}],temporal_operator:'history'},[state('acid-state','CS',acid.text,'2025-01-01',acid.evidence_id),state('ketone-state','CS',ketone.text,'2025-01-01',ketone.evidence_id),state('neuro-state','PE',neuro.text,'2025-01-01',neuro.evidence_id)],[acid,ketone,neuro],{candidate_budget:8,action_budget:6});
  assert.ok(leave.states.some(item=>item.source_type==='query_time_clinical_constraint'&&item.value.includes('不能因为补液后短暂好转就提前离开')));
});

